#!/usr/bin/env bash
# Writes the Homebrew formula for a released CLI version, from the release's checksums.txt.
# Usage: homebrew-formula.sh <version without v> <checksums.txt>  > Formula/certifly.rb
set -euo pipefail
version="$1"
checksums="$2"
base="https://github.com/onesrvnet/certifly/releases/download/v${version}"

sha() {
  local file="certifly_${version}_$1.tar.gz"
  local sum
  sum="$(awk -v f="$file" '$2 == f { print $1 }' "$checksums")"
  if [ -z "$sum" ]; then
    echo "no checksum for $file" >&2
    exit 1
  fi
  echo "$sum"
}

cat <<FORMULA
# Generated by certifly's release workflow; edits are overwritten.
class Certifly < Formula
  desc "SSH access with short-lived certificates from certifly"
  homepage "https://github.com/onesrvnet/certifly"
  version "${version}"
  license "BUSL-1.1"

  on_macos do
    on_arm do
      url "${base}/certifly_${version}_darwin_arm64.tar.gz"
      sha256 "$(sha darwin_arm64)"
    end
    on_intel do
      url "${base}/certifly_${version}_darwin_amd64.tar.gz"
      sha256 "$(sha darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "${base}/certifly_${version}_linux_arm64.tar.gz"
      sha256 "$(sha linux_arm64)"
    end
    on_intel do
      url "${base}/certifly_${version}_linux_amd64.tar.gz"
      sha256 "$(sha linux_amd64)"
    end
  end

  def install
    bin.install "certifly"
    generate_completions_from_executable(bin/"certifly", "completion")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/certifly --version")
  end
end
FORMULA
